package com.oms.supplychain;

import com.oms.supplychain.service.wms.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.oms.supplychain.service.wms.WmsStore.map;

/** Uses the runner's disposable schema, never connects to business databases. */
public class WmsLogQueryTest {
    @Configuration @Import(PurchaseWorkspaceTest.Config.class) static class Config { @Bean WmsLogQuery query(){return new WmsLogQuery();} }
    static AnnotationConfigApplicationContext context;static JdbcTemplate db;static WmsStore store;static WmsLogQuery query;
    @BeforeAll static void open(){context=new AnnotationConfigApplicationContext(Config.class);db=context.getBean(JdbcTemplate.class);store=context.getBean(WmsStore.class);query=context.getBean(WmsLogQuery.class);}
    @AfterAll static void close(){context.close();}
    @BeforeEach void seed(){for(String t:Arrays.asList("wms_outbound_receipt_review","wms_outbound_receipt_event","wms_receipt_line","wms_interaction_log","wms_outbound_task","wms_inbound_task","wms_connection"))db.update("DELETE FROM "+t);connection(1,"QM");connection(2,"ZZ");}
    void connection(long id,String company){store.insert("wms_connection",map("id",id,"company_code",company,"name",company+" TEST","provider","QIMEN","api_version","2.0","environment","TEST","endpoint","http://invalid.local","app_key","key","secret_cipher","NEVER_RETURN_SECRET","callback_key",company+"-callback","enabled",1));}
    void outbound(long id,String company){store.insert("wms_outbound_task",map("id",id,"company_code",company,"shipment_id",id,"shipment_sn","XS"+id,"connection_id",company.equals("QM")?1:2,"external_warehouse","EW","external_owner","EO","real_store_code","W","owner_code","O","payload_json","{}","payload_hash","hash","dispatch_state","ACCEPTED","external_order","WMS"+id,"order_id",12,"order_sn","SO12","platform_tid","900012"));}
    void inbound(long id){store.insert("wms_inbound_task",map("id",id,"company_code","QM","ticket_id",999999,"ticket_sn","RK"+id,"connection_id",1,"external_warehouse","IW","external_owner","IO","dispatch_state","FAILED"));}
    long log(String company,Long task,String sn,String action,String result){return store.insert("wms_interaction_log",map("company_code",company,"connection_id",company.equals("QM")?1:2,"task_id",task,"ticket_sn",sn,"direction",action.endsWith("RECEIPT")?"IN":"OUT","action",action,"request_id",UUID.randomUUID().toString(),"request_body","SECRET_BODY","result",result));}
    Map<String,String> q(String...v){Map<String,String> r=new HashMap<>();for(int i=0;i<v.length;i+=2)r.put(v[i],v[i+1]);return r;}
    @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> response){return (List<Map<String,Object>>)response.get("rows");}
    @Test void taskIdsFromDifferentBusinessTypesCannotMix(){outbound(10,"QM");inbound(10);long out=log("QM",10L,"XS10","OUTBOUND_CREATE","SUCCESS"),in=log("QM",10L,"RK10","CREATE","FAILED");assertEquals("SALE_OUT",query.detail("QM",out).get("business_type"));assertEquals("仓库已受理，等待出库",query.detail("QM",out).get("business_progress"));assertEquals("PURCHASE_IN",query.detail("QM",in).get("business_type"));assertEquals("仓库下发失败",query.detail("QM",in).get("business_progress"));}
    @Test void companyScopeAppliesToListsDetailsOptionsAndAssociations(){outbound(10,"ZZ");long foreign=log("ZZ",10L,"XS10","OUTBOUND_CREATE","SUCCESS");long own=log("QM",10L,"XS10","OUTBOUND_CREATE","FAILED");assertEquals(1,rows(query.list("QM",q())).size());assertThrows(IllegalArgumentException.class,()->query.detail("QM",foreign));assertEquals("未关联业务单据",query.detail("QM",own).get("business_progress"));assertFalse(query.options("QM").toString().contains("ZZ TEST"));assertFalse(query.options("QM").toString().contains("NEVER_RETURN_SECRET"));}
    @Test void exactNumbersSupportOrderPlatformWarehouseAndRequest(){outbound(10,"QM");long id=log("QM",10L,"XS10","OUTBOUND_CREATE","SUCCESS");for(String[] pair:new String[][]{{"ORDER","SO12"},{"PLATFORM","900012"},{"WAREHOUSE","WMS10"},{"DOCUMENT","XS10"},{"REQUEST",query.detail("QM",id).get("request_id").toString()}})assertEquals(1,rows(query.list("QM",q("numberType",pair[0],"number",pair[1],"allTime","true"))).size());assertTrue(rows(query.list("QM",q("numberType","ORDER","number","SO1"))).isEmpty());}
    @Test void cursorPaginationIsStableAtSameTimestampAndDuringNewInserts(){for(int i=0;i<5;i++)log("QM",null,"X","QUERY","SUCCESS");db.update("UPDATE wms_interaction_log SET create_time=DATE_FORMAT(NOW(),'%Y-%m-%d %H:%i:00')");Map<String,Object> first=query.list("QM",q("size","2"));List<Map<String,Object>> a=rows(first);Map<?,?> cursor=(Map<?,?>)first.get("next");log("QM",null,"NEW","QUERY","SUCCESS");Map<String,Object> second=query.list("QM",q("size","2","beforeId",cursor.get("beforeId").toString(),"beforeTime",cursor.get("beforeTime").toString()));List<Map<String,Object>> b=rows(second);assertEquals(2,a.size());assertEquals(2,b.size());assertTrue((Long)a.get(1).get("id")>(Long)b.get(0).get("id"));assertFalse(b.stream().anyMatch(r->"NEW".equals(r.get("ticket_sn"))));}
    @Test void summariesRespectAllFiltersAndDefaultTimeIsBounded(){log("QM",null,"X","QUERY","SUCCESS");long old=log("QM",null,"OLD","QUERY","FAILED");db.update("UPDATE wms_interaction_log SET create_time=DATE_SUB(NOW(),INTERVAL 40 DAY) WHERE id=?",old);assertEquals(1L,query.summary("QM",q()).get("total"));assertEquals(1L,query.summary("QM",q("numberType","DOCUMENT","number","OLD","allTime","true","result","FAILED")).get("total"));assertEquals(0L,query.summary("QM",q("environment","PRODUCTION")).get("total"));}
    @Test void wideScansAndInvalidCursorAreRejectedAndNumbersAreBoundParameters(){assertThrows(IllegalArgumentException.class,()->query.list("QM",q("allTime","true")));assertThrows(IllegalArgumentException.class,()->query.list("QM",q("begin","2026-01-01 00:00:00","end","2026-03-01 00:00:00")));assertThrows(IllegalArgumentException.class,()->query.list("QM",q("beforeId","1")));assertThrows(IllegalArgumentException.class,()->query.list("QM",q("size","4294967346")));assertThrows(IllegalArgumentException.class,()->query.list("QM",q("action","BAD")));assertTrue(rows(query.list("QM",q("numberType","DOCUMENT","number","' OR 1=1 --"))).isEmpty());}
    @Test void interfaceSuccessAndCurrentPostingStatusAreIndependent(){outbound(10,"QM");long log=log("QM",10L,"XS10","OUTBOUND_RECEIPT","SUCCESS");long event=store.insert("wms_outbound_receipt_event",map("company_code","QM","task_id",10,"shipment_sn","XS10","message_id","M1","payload_hash","H","payload_json","{}","quantity",2));assertEquals("回传已接收，记账处理中",query.detail("QM",log).get("business_progress"));db.update("UPDATE wms_outbound_receipt_event SET post_state='FAILED' WHERE id=?",event);assertEquals("回传记账异常",query.detail("QM",log).get("business_progress"));db.update("UPDATE wms_outbound_receipt_event SET post_state='POSTED' WHERE id=?",event);assertEquals("已接收出库回传均已记账",query.detail("QM",log).get("business_progress"));assertEquals("SUCCESS",query.detail("QM",log).get("result"));}
    @Test void pendingConflictIsVisibleWithoutPretendingToDeductStock(){outbound(10,"QM");long id=log("QM",10L,"XS10","OUTBOUND_RECEIPT","FAILED");store.insert("wms_outbound_receipt_review",map("company_code","QM","task_id",10,"shipment_id",10,"shipment_sn","XS10","message_id","R","receipt_hash","H","receipt_json","{}","conflict_code","WAYBILL","conflict_message","冲突","source_log_id",id));assertEquals("出库回传待人工核对，冲突回传未扣账",query.detail("QM",id).get("business_progress"));assertEquals("FAILED",query.detail("QM",id).get("result"));}
    @Test void unassociatedCallbackRemainsVisibleAndPayloadIsNotInMetadata(){long id=log("QM",null,"","OUTBOUND_RECEIPT","FAILED");Map<String,Object> row=query.detail("QM",id);assertEquals("未关联业务单据",row.get("business_progress"));assertFalse(row.containsKey("request_body"));assertFalse(query.list("QM",q()).toString().contains("SECRET_BODY"));assertEquals(1,rows(query.list("QM",q("direction","IN","result","FAILED"))).size());}
    @Test void refundLogsResolveTkWithoutMixingExchangeTaskIds(){db.update("DELETE FROM wms_refund_return_review");db.update("DELETE FROM wms_refund_return");store.insert("wms_refund_return",map("id",900001,"company_code","QM","plan_id",55,"refund_id",20,"return_sn","THK_TEST","refund_sn","TK_TEST","order_sn","SO_TEST","platform_tid","123456","original_shipment_sn","XS_TEST","store_code","V1","sku_sn","A","quantity",5,"connection_id",1,"external_warehouse","EW","external_owner","EO","real_store_code","W","owner_code","O","payload_hash","hash","dispatch_state","ACCEPTED"));long id=log("QM",900001L,"THK_TEST","REFUND_RETURN_RECEIPT","SUCCESS");store.insert("wms_refund_return_review",map("company_code","QM","task_id",900001,"message_id","LATE","payload_hash","hash","payload","{}","quantity",1));db.update("UPDATE wms_interaction_log SET result_summary='本次截单成功，停止剩余7件' WHERE id=?",id);Map<String,Object> row=query.detail("QM",id);assertEquals("本次截单成功，停止剩余7件",row.get("result_summary"));assertEquals("REFUND_IN",row.get("business_type"));assertEquals("TK_TEST",row.get("business_owner_sn"));assertEquals("退回回传待人工核对，冲突回传未入账",row.get("business_progress"));assertEquals(1,rows(query.list("QM",q("numberType","REFUND","number","TK_TEST","allTime","true"))).size());assertEquals(0,rows(query.list("QM",q("numberType","EXCHANGE","number","TK_TEST","allTime","true"))).size());}
}
